mapper.select:
SELECT result_id AS resultId, test_case_key AS testCaseKey,
  test_name AS testName, status, duration_ms AS durationMs, http_method AS httpMethod,
  http_status AS httpStatus, error_summary AS errorSummary, skip_reason AS skipReason
  FROM modernization_test_result WHERE run_id=#{runId}
  AND status=#{status}
  ORDER BY result_id

SELECT 
  FROM modernization_test_run WHERE module=#{module} AND test_type=#{testType}
  ORDER BY started_at DESC, run_id DESC LIMIT 1
